function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Each value is an integer from 0 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > Math.min(70, nums.length)) return 'k is between 1 and min(70, nums.length).';
  return null;
}

