function minMaxSums(nums, k) {
  const MOD = 1e9 + 7;
  const n = nums.length;
  nums.sort((a, b) => a - b);
  // row[j] = C(m, j): ways to pick j of the m indices on one side.
  const row = new Array(k).fill(0);
  row[0] = 1;
  let total = 0;
  for (let m = 0; m < n; m++) {
    let ways = 0;
    for (let j = 0; j < k; j++) {
      ways = (ways + row[j]) % MOD;
    }
    const pair = nums[m] + nums[n - 1 - m];
    const contribution = Number((BigInt(pair) * BigInt(ways)) % BigInt(MOD));
    total = (total + contribution) % MOD;
    for (let j = k - 1; j > 0; j--) {
      row[j] = (row[j] + row[j - 1]) % MOD;
    }
  }
  return total;
}

