function minMaxSums(nums, k) {
  // Try every non-empty set of positions and keep those with at most k members.
  const MOD = 1e9 + 7;
  const n = nums.length;
  let total = 0;
  for (let mask = 1; mask < (1 << n); mask++) {
    let size = 0;
    let low = Infinity;
    let high = -Infinity;
    for (let i = 0; i < n; i++) {
      if ((mask >> i) & 1) {
        size++;
        low = Math.min(low, nums[i]);
        high = Math.max(high, nums[i]);
      }
    }
    if (size <= k) total = (total + low + high) % MOD;
  }
  return total;
}

