function generate(rand, size) {
  const pick = count => Math.floor(rand() * count);
  const n = size === 'large' ? 1900 + pick(101) : 1 + pick(10);
  // Tiny value ranges create many ties; the full range makes the total wrap around the modulus.
  const top = [3, 100, 1000000000][pick(3)];
  const nums = Array.from({ length: n }, () => pick(top + 1));
  const limit = Math.min(70, n);
  const k = size === 'large' && rand() < 0.5 ? limit : 1 + pick(limit);
  return [nums, k];
}
